package report

import (
	"testing"

	"navsvc/pkg/api"
)

func TestNamelessRecordsAreNotCounted(t *testing.T) {
	s := NewSummary()
	s.Observe(api.Batch{Records: []api.Record{
		{Name: "a", Value: 1, Valid: true},
		{Name: "", Value: 9, Valid: true},
	}})
	out := s.Render()
	if out != "a count=1 total=1\n" {
		t.Fatalf("nameless record leaked into the summary: %q", out)
	}
}

func TestResetClearsAccumulatedState(t *testing.T) {
	s := NewSummary()
	s.Observe(api.Batch{Records: []api.Record{{Name: "a", Value: 1, Valid: true}}})
	s.Reset()
	if out := s.Render(); out != "" {
		t.Fatalf("Reset left state behind: %q", out)
	}
	s.Observe(api.Batch{Records: []api.Record{{Name: "b", Value: 2, Valid: true}}})
	if out := s.Render(); out != "b count=1 total=2\n" {
		t.Fatalf("summary unusable after Reset: %q", out)
	}
}
