import (
	"testing"

	"navsvc/pkg/api"
)

func TestEverySinkRefusesWriteAfterClose(t *testing.T) {
	batch := api.Batch{Records: []api.Record{{Name: "a", Value: 1, Valid: true}}}
	for _, name := range []string{"stdout", "file", "null"} {
		s, ok := For(name)
		if !ok {
			t.Fatalf("sink %q missing", name)
		}
		if err := s.Write(batch); err != nil {
			t.Fatalf("%s: write before close failed: %v", name, err)
		}
		if err := s.Close(); err != nil {
			t.Fatalf("%s: close failed: %v", name, err)
		}
		if err := s.Write(batch); err == nil {
			t.Fatalf("%s: write after close must fail", name)
		}
	}
}
