package report

import (
	"testing"

	"navsvc/pkg/api"
)

func rb(values ...float64) []api.Batch {
	records := make([]api.Record, 0, len(values))
	for _, value := range values {
		records = append(records, api.Record{Name: "m", Value: value, Valid: true})
	}
	return []api.Batch{{Records: records}}
}

func TestMaxValueSurvivesAllNegativeInput(t *testing.T) {
	if got := MaxValue(rb(-3, -1)); got != -1 {
		t.Fatalf("MaxValue([-3,-1]): want -1, got %g", got)
	}
	if got := MaxValue(rb(2, 5, 3)); got != 5 {
		t.Fatalf("MaxValue([2,5,3]): want 5, got %g", got)
	}
	if got := MaxValue(nil); got != 0 {
		t.Fatalf("MaxValue(empty): want 0, got %g", got)
	}
}

func TestMinValueBehaviourIsPinned(t *testing.T) {
	if got := MinValue(rb(2, 5)); got != 2 {
		t.Fatalf("MinValue([2,5]): want 2, got %g", got)
	}
	if got := MinValue(rb(-3, -1)); got != -3 {
		t.Fatalf("MinValue([-3,-1]): want -3, got %g", got)
	}
	if got := MinValue(nil); got != 0 {
		t.Fatalf("MinValue(empty): want 0, got %g", got)
	}
}
